struct Order {
    let id: OrderId
    private let creditLimitCents: Int64
    private(set) var lines: [OrderLine] = []
    private(set) var totalCents: Int64 = 0
    mutating func addLine(_ line: OrderLine) throws {
        guard totalCents + line.amountCents <= creditLimitCents else {
            throw DomainError.creditLimitExceeded
        }
        lines.append(line)
        totalCents += line.amountCents
    }
}
